  --text-secondary: #4b5563;
  --text-muted: #6b7280;
  --text-light: #9ca3af;
  --border: #e5e7eb;
  --border-light: #f0f0f5;
  --radius: 8px;
  --radius-lg: 12px;
  --radius-sm: 6px;
  --shadow-sm: 0 1px 3px rgba(0,0,0,0.06);
  --shadow: 0 2px 8px rgba(0,0,0,0.08);
  --shadow-lg: 0 4px 20px rgba(0,0,0,0.1);
  --max-width: 1200px;
  --header-height: 64px;
  --font: 'Inter', system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  --tag-ai: #7c3aed;
  --tag-scraping: #059669;
  --tag-databases: #ea580c;
  --tag-elasticsearch: #0d9488;
  --tag-data-eng: #dc2626;
  --tag-js: #d97706;
  --tag-python: #2563eb;
  --tag-general: #4f46e5;
  --tag-react: #0891b2;
  --tag-ai-bg: #f5f3ff;
  --tag-scraping-bg: #ecfdf5;
  --tag-databases-bg: #fff7ed;
  --tag-elasticsearch-bg: #f0fdfa;
  --tag-data-eng-bg: #fef2f2;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

body {
  font-family: var(--font);
  color: var(--text);
  background: var(--bg);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

img { max-width: 100%; display: block; }
a { color: var(--link); text-decoration: none; }
a:hover { color: var(--link-hover); }
ul { list-style: none; }

/* ── Header ── */
.site-header {
  background: var(--primary);
