  transition: background 0.2s;
}
.donate-btn:hover { background: var(--accent-hover); }
.donate-sub {
  text-align: center;
  font-size: 0.8rem;
  color: var(--text-muted);
  margin-top: 12px;
}
.donate-sub a { color: var(--link); }

.benefits-section {
  max-width: var(--max-width);
  margin: 48px auto;
  padding: 0 24px;
}
.benefits-section h2 { font-size: 1.5rem; font-weight: 700; margin-bottom: 20px; }
.benefits-list {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 12px;
}
.benefit-item {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 16px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
}
.benefit-icon {
  width: 24px; height: 24px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--accent);
  flex-shrink: 0;
  font-size: 1.1rem;
}

.initiatives-section {
  max-width: var(--max-width);
  margin: 48px auto;
  padding: 0 24px;
}
.initiatives-section h2 { font-size: 1.5rem; font-weight: 700; margin-bottom: 20px; }
.initiative-list { display: flex; flex-direction: column; gap: 12px; }
.initiative-item {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 16px 20px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  font-size: 0.95rem;
}
.initiative-dot {
  width: 10px; height: 10px;
  border-radius: 50%;
  background: var(--accent);
  flex-shrink: 0;
}

.achievements-section {
  max-width: var(--max-width);
  margin: 48px auto;
  padding: 0 24px;
}
.achievements-section h2 { font-size: 1.5rem; font-weight: 700; margin-bottom: 20px; }
.achievements-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.achievements-list li {
  padding: 18px 20px;
  border-left: 3px solid var(--accent);
  background: var(--bg-light);
  border-radius: 0 var(--radius-sm) var(--radius-sm) 0;
  font-size: 0.95rem;
  color: var(--text-secondary);
}
.achievements-list li strong {
  color: var(--text);
  display: block;
  font-size: 1.3rem;
  margin-bottom: 2px;
}

/* ── FAQ Accordion ── */
.faq-section {
  max-width: var(--max-width);
  margin: 48px auto;
  padding: 0 24px;
}
.faq-section h2 { font-size: 1.5rem; font-weight: 700; margin-bottom: 24px; }
.faq-list { display: flex; flex-direction: column; gap: 8px; }
.faq-item { border: 1px solid var(--border); border-radius: var(--radius); overflow: hidden; }
.faq-question {
  width: 100%;
  padding: 18px 20px;
  background: var(--bg);
  border: none;
  text-align: left;
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--text);
  cursor: pointer;
  font-family: var(--font);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  transition: background 0.2s;
}
.faq-question:hover { background: var(--bg-light); }
.faq-question .faq-arrow {
  width: 20px; height: 20px;
  flex-shrink: 0;
  transition: transform 0.3s;
  color: var(--text-muted);
}
.faq-item.open .faq-arrow { transform: rotate(180deg); color: var(--accent); }
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.35s ease, padding 0.35s ease;
}
.faq-item.open .faq-answer {
  max-height: 300px;
  padding: 0 20px 18px;
}
.faq-answer p {
  font-size: 0.9rem;
  color: var(--text-secondary);
  line-height: 1.7;
  padding-top: 4px;
  border-top: 1px solid var(--border-light);
}

/* ── Tag Pages ── */
.tag-header-section {
  max-width: var(--max-width);
  margin: 40px auto 0;
  padding: 0 24px;
}
.tag-header-section h1 {
  font-size: 2rem;
  font-weight: 700;
  margin-bottom: 6px;
}
.tag-header-section h1 .tag-label {
  font-size: 1.5rem;
  vertical-align: middle;
}
.tag-post-count {
  font-size: 1rem;
  color: var(--text-muted);
}
.popular-tags-section {
  max-width: var(--max-width);
  margin: 28px auto;
  padding: 0 24px;
}
.popular-tags-section h3 {
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 12px;
}
.popular-tags-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
.popular-tag-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 14px;
  border: 1px solid var(--border);
  border-radius: 100px;
  font-size: 0.8rem;
  font-weight: 500;
  color: var(--text-secondary);
  background: var(--bg);
  transition: all 0.2s;
  white-space: nowrap;
}
.popular-tag-chip:hover {
  border-color: var(--text-muted);
  background: var(--bg-light);
}
.popular-tag-chip .chip-count {
  color: var(--text-muted);
  font-size: 0.75rem;
}

/* ── Section Wrapper ── */
.section-wrap {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

/* ── Responsive ── */
@media (max-width: 1024px) {
  .article-grid { grid-template-columns: repeat(2, 1fr); }
  .curriculum-grid { grid-template-columns: repeat(2, 1fr); }
  .featured-card { grid-template-columns: 1fr; }
  .featured-thumb { min-height: 220px; }
}

@media (max-width: 768px) {
  .header-search { display: none; }
  .header-nav { display: none; }
  .header-nav.open {
    display: flex;
    flex-direction: column;
    position: absolute;
    top: var(--header-height);
    left: 0;
    right: 0;
    background: var(--primary);
    padding: 16px 24px;
    gap: 4px;
    border-top: 1px solid var(--primary-lighter);
  }
  .header-nav.open a {
    padding: 12px 16px;
    width: 100%;
    border-radius: var(--radius-sm);
  }
  .header-nav .nav-donate { margin-left: 0; }
  .hamburger { display: flex; }
  .article-grid { grid-template-columns: 1fr; }
  .curriculum-grid { grid-template-columns: 1fr; }
  .course-list { grid-template-columns: 1fr; }
  .benefits-list { grid-template-columns: 1fr; }
  .featured-card { grid-template-columns: 1fr; }
  .featured-thumb { min-height: 200px; }
  .featured-body { padding: 24px; }
  .featured-body h2 { font-size: 1.35rem; }
  .amount-tabs { grid-template-columns: repeat(4, 1fr); }
  .amount-tab { font-size: 1rem; padding: 12px 4px; }
  .donate-hero h1 { font-size: 1.75rem; }
  .daily-challenge-inner { flex-direction: column; text-align: center; }
  .banner-inner { font-size: 0.8rem; }
}

@media (max-width: 480px) {
  .amount-tabs { grid-template-columns: repeat(2, 1fr); }
  .header-logo { font-size: 1rem; }
  .section-title { font-size: 1.25rem; }
}
