/* OpenLearnHub — Design System */
:root {
  --primary: #0a0a23;
  --primary-light: #1a1a3e;
  --primary-lighter: #2a2a4e;
  --accent: #FEAC32;
  --accent-hover: #e5991f;
  --accent-light: #fff3d6;
  --link: #002EAD;
  --link-hover: #001f7a;
  --bg: #ffffff;
  --bg-light: #f8f9fa;
  --bg-cream: #fef9ef;
  --bg-warm: #fffbf5;
  --text: #1a1a2e;
  --text-secondary: #4b5563;
  --text-muted: #6b7280;
  --text-light: #9ca3af;
  --border: #e5e7eb;
  --border-light: #f0f0f5;
  --radius: 8px;
  --radius-lg: 12px;
  --radius-sm: 6px;
  --shadow-sm: 0 1px 3px rgba(0,0,0,0.06);
  --shadow: 0 2px 8px rgba(0,0,0,0.08);
  --shadow-lg: 0 4px 20px rgba(0,0,0,0.1);
  --max-width: 1200px;
  --header-height: 64px;
  --font: 'Inter', system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  --tag-ai: #7c3aed;
  --tag-scraping: #059669;
  --tag-databases: #ea580c;
  --tag-elasticsearch: #0d9488;
  --tag-data-eng: #dc2626;
  --tag-js: #d97706;
  --tag-python: #2563eb;
  --tag-general: #4f46e5;
  --tag-react: #0891b2;
  --tag-ai-bg: #f5f3ff;
  --tag-scraping-bg: #ecfdf5;
  --tag-databases-bg: #fff7ed;
  --tag-elasticsearch-bg: #f0fdfa;
  --tag-data-eng-bg: #fef2f2;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

body {
  font-family: var(--font);
  color: var(--text);
  background: var(--bg);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

img { max-width: 100%; display: block; }
a { color: var(--link); text-decoration: none; }
a:hover { color: var(--link-hover); }
ul { list-style: none; }

/* ── Header ── */
.site-header {
  background: var(--primary);
  color: #fff;
  position: sticky;
  top: 0;
  z-index: 100;
  height: var(--header-height);
}
.header-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
  height: 100%;
  display: flex;
  align-items: center;
  gap: 24px;
}
.header-logo {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 1.25rem;
  font-weight: 700;
  color: #fff;
  white-space: nowrap;
}
.header-logo:hover { color: var(--accent); }
.header-logo-icon {
  width: 32px; height: 32px;
  background: var(--accent);
  color: var(--primary);
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
  font-size: 1rem;
  flex-shrink: 0;
}

.header-search {
  flex: 1;
  max-width: 420px;
  position: relative;
}
.header-search input {
  width: 100%;
  padding: 8px 12px 8px 36px;
  border-radius: 20px;
  border: none;
  background: var(--primary-lighter);
  color: #fff;
  font-size: 0.875rem;
  font-family: var(--font);
  outline: none;
  transition: background 0.2s;
}
.header-search input::placeholder { color: var(--text-light); }
.header-search input:focus { background: #3a3a5e; }
.header-search .search-icon {
  position: absolute;
  left: 12px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--text-light);
  pointer-events: none;
}

.header-nav {
  display: flex;
  align-items: center;
  gap: 4px;
}
.header-nav a {
  color: #fff;
  padding: 8px 16px;
  border-radius: var(--radius-sm);
  font-size: 0.9rem;
  transition: background 0.2s;
}
.header-nav a:hover { background: var(--primary-lighter); color: var(--accent); }
.header-nav .nav-donate {
  background: var(--accent);
  color: var(--primary);
  font-weight: 600;
  margin-left: 8px;
}
.header-nav .nav-donate:hover { background: var(--accent-hover); color: var(--primary); }

.hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  background: none;
  border: none;
  cursor: pointer;
  padding: 8px;
  z-index: 101;
}
.hamburger span {
  display: block;
  width: 24px;
  height: 2px;
  background: #fff;
  border-radius: 2px;
  transition: all 0.3s;
}
.hamburger.active span:nth-child(1) { transform: rotate(45deg) translate(5px, 5px); }
.hamburger.active span:nth-child(2) { opacity: 0; }
.hamburger.active span:nth-child(3) { transform: rotate(-45deg) translate(5px, -5px); }

/* ── Banner ── */
.banner {
  background: var(--bg-cream);
  border-bottom: 1px solid var(--border);
  padding: 10px 0;
}
.banner-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 0.9rem;
  color: var(--text-secondary);
}
.banner-inner a { font-weight: 600; color: var(--link); }
.banner-inner a:hover { text-decoration: underline; }
.banner-dot {
  width: 6px; height: 6px;
  background: var(--accent);
  border-radius: 50%;
  flex-shrink: 0;
}

/* ── Featured Article ── */
.featured {
  max-width: var(--max-width);
  margin: 40px auto 0;
  padding: 0 24px;
}
.featured-card {
  display: grid;
  grid-template-columns: 1fr 1fr;
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: var(--bg);
  border: 1px solid var(--border);
  transition: box-shadow 0.2s;
}
.featured-card:hover { box-shadow: var(--shadow-lg); }
.featured-thumb {
  background: linear-gradient(135deg, #4c1d95 0%, #7c3aed 50%, #a78bfa 100%);
  min-height: 320px;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}
.featured-thumb .thumb-icon {
  font-size: 5rem;
  opacity: 0.3;
  color: #fff;
}
.featured-body {
  padding: 36px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 16px;
}
.featured-body .tag { align-self: flex-start; }
.featured-body h2 {
  font-size: 1.75rem;
  font-weight: 700;
  line-height: 1.3;
  color: var(--text);
}
.featured-body h2 a { color: inherit; }
.featured-body h2 a:hover { color: var(--link); }
.featured-meta {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 0.875rem;
  color: var(--text-muted);
}
.featured-meta .author { font-weight: 600; color: var(--text); }

/* ── Article Grid ── */
.article-section {
  max-width: var(--max-width);
  margin: 48px auto;
  padding: 0 24px;
}
.section-title {
  font-size: 1.5rem;
  font-weight: 700;
  margin-bottom: 28px;
  color: var(--text);
}
.article-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}
.article-card {
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: box-shadow 0.2s, transform 0.2s;
}
.article-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}
.card-thumb {
  height: 180px;
  position: relative;
  overflow: hidden;
}
.card-thumb-inner {
  width: 100%; height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 3rem;
  opacity: 0.2;
  color: #fff;
}
.card-tag-overlay {
  position: absolute;
  top: 12px;
  left: 12px;
}
.card-body {
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.card-body h3 {
  font-size: 1.1rem;
  font-weight: 600;
  line-height: 1.4;
}
.card-body h3 a { color: var(--text); }
.card-body h3 a:hover { color: var(--link); }
.card-meta {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 0.8rem;
  color: var(--text-muted);
}

/* ── Tags ── */
.tag {
  display: inline-block;
  padding: 3px 10px;
  border-radius: 100px;
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  white-space: nowrap;
}
.tag-ai { background: var(--tag-ai-bg); color: var(--tag-ai); }
.tag-scraping { background: var(--tag-scraping-bg); color: var(--tag-scraping); }
.tag-databases { background: var(--tag-databases-bg); color: var(--tag-databases); }
.tag-elasticsearch { background: var(--tag-elasticsearch-bg); color: var(--tag-elasticsearch); }
.tag-data-eng { background: var(--tag-data-eng-bg); color: var(--tag-data-eng); }
.tag-js { background: #fef3c7; color: #92400e; }
.tag-python { background: #dbeafe; color: #1e40af; }
.tag-general { background: #eef2ff; color: #3730a3; }
.tag-react { background: #ecfeff; color: #155e75; }
.tag-tech { background: #f0fdf4; color: #166534; }
.tag-youtube { background: #fef2f2; color: #991b1b; }
.tag-startup { background: #fdf4ff; color: #86198f; }
.tag-design { background: #fff7ed; color: #9a3412; }
.tag-productivity { background: #f0fdfa; color: #115e59; }
.tag-life { background: #fefce8; color: #854d0e; }
.tag-css { background: #eff6ff; color: #1e40af; }
.tag-self { background: #f5f3ff; color: #5b21b6; }
.tag-node { background: #ecfdf5; color: #065f46; }
.tag-sheets { background: #f0fdf4; color: #166534; }

/* ── Avatar ── */
.avatar {
  width: 28px; height: 28px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.7rem;
  font-weight: 700;
  color: #fff;
  flex-shrink: 0;
}
.avatar-sm { width: 24px; height: 24px; font-size: 0.6rem; }

/* ── Load More ── */
.load-more-wrap {
  text-align: center;
  margin-top: 36px;
}
.load-more-btn {
  padding: 14px 40px;
  border: 2px solid var(--border);
  border-radius: 100px;
  background: var(--bg);
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--text);
  cursor: pointer;
  font-family: var(--font);
  transition: all 0.2s;
}
.load-more-btn:hover {
  border-color: var(--primary);
  background: var(--primary);
  color: #fff;
}
.load-more-btn:active { transform: scale(0.98); }

/* ── Footer ── */
.site-footer {
  background: var(--primary);
  color: #ccc;
  padding: 48px 24px 32px;
  margin-top: 64px;
}
.footer-inner {
  max-width: var(--max-width);
  margin: 0 auto;
}
.footer-mission {
  max-width: 680px;
  margin-bottom: 32px;
  font-size: 0.9rem;
  line-height: 1.7;
  color: var(--text-light);
}
.footer-guides h4 {
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--accent);
  margin-bottom: 12px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}
.footer-guides .guide-links {
  display: flex;
  flex-wrap: wrap;
  gap: 6px 16px;
  margin-bottom: 32px;
  font-size: 0.875rem;
}
.footer-guides .guide-links a { color: var(--text-light); }
.footer-guides .guide-links a:hover { color: #fff; }
.footer-guides .guide-links span { color: var(--text-muted); }
.footer-links {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 20px;
  font-size: 0.8rem;
  border-top: 1px solid var(--primary-lighter);
  padding-top: 24px;
}
.footer-links a { color: var(--text-muted); }
.footer-links a:hover { color: #fff; }

/* ── Learn Page ── */
.learn-welcome {
  max-width: var(--max-width);
  margin: 40px auto 0;
  padding: 0 24px;
  text-align: center;
}
.learn-welcome h1 {
  font-size: 2rem;
  font-weight: 700;
  margin-bottom: 8px;
}
.learn-welcome p { color: var(--text-muted); font-size: 1.05rem; }
.learn-welcome .signin-link {
  display: inline-block;
  margin-top: 12px;
  padding: 8px 24px;
  background: var(--accent);
  color: var(--primary);
  font-weight: 600;
  border-radius: 100px;
  font-size: 0.9rem;
}
.learn-welcome .signin-link:hover { background: var(--accent-hover); color: var(--primary); }

.curriculum-section {
  max-width: var(--max-width);
  margin: 48px auto;
  padding: 0 24px;
}
.curriculum-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}
.curriculum-card {
  display: flex;
  align-items: flex-start;
  gap: 16px;
  padding: 24px;
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  transition: box-shadow 0.2s;
}
.curriculum-card:hover { box-shadow: var(--shadow); }
.curriculum-icon {
  width: 48px; height: 48px;
  border-radius: var(--radius);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
  flex-shrink: 0;
}
.curriculum-card h3 { font-size: 0.95rem; font-weight: 600; line-height: 1.4; }
.curriculum-meta { font-size: 0.8rem; color: var(--text-muted); margin-top: 4px; }

.daily-challenge {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 32px 24px;
  background: var(--bg-cream);
  border-radius: var(--radius-lg);
}
.daily-challenge-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 16px;
}
.daily-challenge h3 { font-size: 1.1rem; font-weight: 600; }
.daily-challenge .challenge-links { display: flex; gap: 16px; }
.daily-challenge .challenge-links a {
  padding: 10px 24px;
  border-radius: 100px;
  font-weight: 600;
  font-size: 0.9rem;
}
.btn-primary {
  background: var(--accent);
  color: var(--primary);
}
.btn-primary:hover { background: var(--accent-hover); color: var(--primary); }
.btn-secondary {
  border: 2px solid var(--border);
  color: var(--text);
}
.btn-secondary:hover { border-color: var(--text); color: var(--text); }

.course-section {
  max-width: var(--max-width);
  margin: 48px auto;
  padding: 0 24px;
}
.course-section h2 { font-size: 1.35rem; font-weight: 700; margin-bottom: 20px; }
.course-list {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 12px;
}
.course-item {
  padding: 16px 20px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  display: flex;
  align-items: center;
  gap: 12px;
  transition: background 0.2s;
}
.course-item:hover { background: var(--bg-light); }
.course-item .course-dot {
  width: 8px; height: 8px;
  border-radius: 50%;
  background: var(--accent);
  flex-shrink: 0;
}
.course-item .course-badge {
  font-size: 0.7rem;
  font-weight: 600;
  padding: 2px 8px;
  border-radius: 100px;
  background: var(--accent-light);
  color: var(--primary);
  white-space: nowrap;
}

/* ── Donate Page ── */
.donate-hero {
  max-width: var(--max-width);
  margin: 48px auto;
  padding: 0 24px;
  text-align: center;
}
.donate-hero h1 {
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--text);
  margin-bottom: 16px;
}
.donate-hero p {
  max-width: 640px;
  margin: 0 auto;
  color: var(--text-secondary);
  font-size: 1.1rem;
  line-height: 1.7;
}
.donate-form-wrap {
  max-width: 520px;
  margin: 40px auto;
  padding: 36px;
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow);
}
.amount-tabs {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
  margin-bottom: 20px;
}
.amount-tab {
  padding: 14px 8px;
  border: 2px solid var(--border);
  border-radius: var(--radius);
  background: var(--bg);
  font-size: 1.15rem;
  font-weight: 700;
  cursor: pointer;
  font-family: var(--font);
  color: var(--text);
  transition: all 0.2s;
  text-align: center;
}
.amount-tab:hover { border-color: var(--accent); }
.amount-tab.active {
  border-color: var(--accent);
  background: var(--accent);
  color: var(--primary);
}
.donation-description {
  text-align: center;
  font-size: 0.9rem;
  color: var(--text-secondary);
  margin-bottom: 24px;
  padding: 16px;
  background: var(--bg-light);
  border-radius: var(--radius);
  min-height: 72px;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.3s;
}
.donate-btn {
  display: block;
  width: 100%;
  padding: 16px;
  background: var(--accent);
  color: var(--primary);
  border: none;
  border-radius: var(--radius);
  font-size: 1.1rem;
  font-weight: 700;
  cursor: pointer;
  font-family: var(--font);
  transition: background 0.2s;
}
.donate-btn:hover { background: var(--accent-hover); }
.donate-sub {
  text-align: center;
  font-size: 0.8rem;
  color: var(--text-muted);
  margin-top: 12px;
}
.donate-sub a { color: var(--link); }

.benefits-section {
  max-width: var(--max-width);
  margin: 48px auto;
  padding: 0 24px;
}
.benefits-section h2 { font-size: 1.5rem; font-weight: 700; margin-bottom: 20px; }
.benefits-list {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 12px;
}
.benefit-item {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 16px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
}
.benefit-icon {
  width: 24px; height: 24px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--accent);
  flex-shrink: 0;
  font-size: 1.1rem;
}

.initiatives-section {
  max-width: var(--max-width);
  margin: 48px auto;
  padding: 0 24px;
}
.initiatives-section h2 { font-size: 1.5rem; font-weight: 700; margin-bottom: 20px; }
.initiative-list { display: flex; flex-direction: column; gap: 12px; }
.initiative-item {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 16px 20px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  font-size: 0.95rem;
}
.initiative-dot {
  width: 10px; height: 10px;
  border-radius: 50%;
  background: var(--accent);
  flex-shrink: 0;
}

.achievements-section {
  max-width: var(--max-width);
  margin: 48px auto;
  padding: 0 24px;
}
.achievements-section h2 { font-size: 1.5rem; font-weight: 700; margin-bottom: 20px; }
.achievements-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.achievements-list li {
  padding: 18px 20px;
  border-left: 3px solid var(--accent);
  background: var(--bg-light);
  border-radius: 0 var(--radius-sm) var(--radius-sm) 0;
  font-size: 0.95rem;
  color: var(--text-secondary);
}
.achievements-list li strong {
  color: var(--text);
  display: block;
  font-size: 1.3rem;
  margin-bottom: 2px;
}

/* ── FAQ Accordion ── */
.faq-section {
  max-width: var(--max-width);
  margin: 48px auto;
  padding: 0 24px;
}
.faq-section h2 { font-size: 1.5rem; font-weight: 700; margin-bottom: 24px; }
.faq-list { display: flex; flex-direction: column; gap: 8px; }
.faq-item { border: 1px solid var(--border); border-radius: var(--radius); overflow: hidden; }
.faq-question {
  width: 100%;
  padding: 18px 20px;
  background: var(--bg);
  border: none;
  text-align: left;
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--text);
  cursor: pointer;
  font-family: var(--font);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  transition: background 0.2s;
}
.faq-question:hover { background: var(--bg-light); }
.faq-question .faq-arrow {
  width: 20px; height: 20px;
  flex-shrink: 0;
  transition: transform 0.3s;
  color: var(--text-muted);
}
.faq-item.open .faq-arrow { transform: rotate(180deg); color: var(--accent); }
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.35s ease, padding 0.35s ease;
}
.faq-item.open .faq-answer {
  max-height: 300px;
  padding: 0 20px 18px;
}
.faq-answer p {
  font-size: 0.9rem;
  color: var(--text-secondary);
  line-height: 1.7;
  padding-top: 4px;
  border-top: 1px solid var(--border-light);
}

/* ── Tag Pages ── */
.tag-header-section {
  max-width: var(--max-width);
  margin: 40px auto 0;
  padding: 0 24px;
}
.tag-header-section h1 {
  font-size: 2rem;
  font-weight: 700;
  margin-bottom: 6px;
}
.tag-header-section h1 .tag-label {
  font-size: 1.5rem;
  vertical-align: middle;
}
.tag-post-count {
  font-size: 1rem;
  color: var(--text-muted);
}
.popular-tags-section {
  max-width: var(--max-width);
  margin: 28px auto;
  padding: 0 24px;
}
.popular-tags-section h3 {
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 12px;
}
.popular-tags-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
.popular-tag-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 14px;
  border: 1px solid var(--border);
  border-radius: 100px;
  font-size: 0.8rem;
  font-weight: 500;
  color: var(--text-secondary);
  background: var(--bg);
  transition: all 0.2s;
  white-space: nowrap;
}
.popular-tag-chip:hover {
  border-color: var(--text-muted);
  background: var(--bg-light);
}
.popular-tag-chip .chip-count {
  color: var(--text-muted);
  font-size: 0.75rem;
}

/* ── Section Wrapper ── */
.section-wrap {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

/* ── Responsive ── */
@media (max-width: 1024px) {
  .article-grid { grid-template-columns: repeat(2, 1fr); }
  .curriculum-grid { grid-template-columns: repeat(2, 1fr); }
  .featured-card { grid-template-columns: 1fr; }
  .featured-thumb { min-height: 220px; }
}

@media (max-width: 768px) {
  .header-search { display: none; }
  .header-nav { display: none; }
  .header-nav.open {
    display: flex;
    flex-direction: column;
    position: absolute;
    top: var(--header-height);
    left: 0;
    right: 0;
    background: var(--primary);
    padding: 16px 24px;
    gap: 4px;
    border-top: 1px solid var(--primary-lighter);
  }
  .header-nav.open a {
    padding: 12px 16px;
    width: 100%;
    border-radius: var(--radius-sm);
  }
  .header-nav .nav-donate { margin-left: 0; }
  .hamburger { display: flex; }
  .article-grid { grid-template-columns: 1fr; }
  .curriculum-grid { grid-template-columns: 1fr; }
  .course-list { grid-template-columns: 1fr; }
  .benefits-list { grid-template-columns: 1fr; }
  .featured-card { grid-template-columns: 1fr; }
  .featured-thumb { min-height: 200px; }
  .featured-body { padding: 24px; }
  .featured-body h2 { font-size: 1.35rem; }
  .amount-tabs { grid-template-columns: repeat(4, 1fr); }
  .amount-tab { font-size: 1rem; padding: 12px 4px; }
  .donate-hero h1 { font-size: 1.75rem; }
  .daily-challenge-inner { flex-direction: column; text-align: center; }
  .banner-inner { font-size: 0.8rem; }
}

@media (max-width: 480px) {
  .amount-tabs { grid-template-columns: repeat(2, 1fr); }
  .header-logo { font-size: 1rem; }
  .section-title { font-size: 1.25rem; }
}

/* OpenLearnHub — Design System */
:root {
  --primary: #0a0a23;
  --primary-light: #1a1a3e;
  --primary-lighter: #2a2a4e;
  --accent: #FEAC32;
  --accent-hover: #e5991f;
  --accent-light: #fff3d6;
  --link: #002EAD;
  --link-hover: #001f7a;
  --bg: #ffffff;
  --bg-light: #f8f9fa;
  --bg-cream: #fef9ef;
  --bg-warm: #fffbf5;
  --text: #1a1a2e;
  --text-secondary: #4b5563;
  --text-muted: #6b7280;
  --text-light: #9ca3af;
  --border: #e5e7eb;
  --border-light: #f0f0f5;
  --radius: 8px;
  --radius-lg: 12px;
  --radius-sm: 6px;
  --shadow-sm: 0 1px 3px rgba(0,0,0,0.06);
  --shadow: 0 2px 8px rgba(0,0,0,0.08);
  --shadow-lg: 0 4px 20px rgba(0,0,0,0.1);
  --max-width: 1200px;
  --header-height: 64px;
  --font: 'Inter', system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  --tag-ai: #7c3aed;
  --tag-scraping: #059669;
  --tag-databases: #ea580c;
  --tag-elasticsearch: #0d9488;
  --tag-data-eng: #dc2626;
  --tag-js: #d97706;
  --tag-python: #2563eb;
  --tag-general: #4f46e5;
  --tag-react: #0891b2;
  --tag-ai-bg: #f5f3ff;
  --tag-scraping-bg: #ecfdf5;
  --tag-databases-bg: #fff7ed;
  --tag-elasticsearch-bg: #f0fdfa;
  --tag-data-eng-bg: #fef2f2;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

body {
  font-family: var(--font);
  color: var(--text);
  background: var(--bg);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

img { max-width: 100%; display: block; }
a { color: var(--link); text-decoration: none; }
a:hover { color: var(--link-hover); }
ul { list-style: none; }

/* ── Header ── */
.site-header {
  background: var(--primary);
  color: #fff;
  position: sticky;
  top: 0;
  z-index: 100;
  height: var(--header-height);
}
.header-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
  height: 100%;
  display: flex;
  align-items: center;
  gap: 24px;
}
.header-logo {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 1.25rem;
  font-weight: 700;
  color: #fff;
  white-space: nowrap;
}
.header-logo:hover { color: var(--accent); }
.header-logo-icon {
  width: 32px; height: 32px;
  background: var(--accent);
  color: var(--primary);
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
  font-size: 1rem;
  flex-shrink: 0;
}

.header-search {
  flex: 1;
  max-width: 420px;
  position: relative;
}
.header-search input {
  width: 100%;
  padding: 8px 12px 8px 36px;
  border-radius: 20px;
  border: none;
  background: var(--primary-lighter);
  color: #fff;
  font-size: 0.875rem;
  font-family: var(--font);
  outline: none;
  transition: background 0.2s;
}
.header-search input::placeholder { color: var(--text-light); }
.header-search input:focus { background: #3a3a5e; }
.header-search .search-icon {
  position: absolute;
  left: 12px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--text-light);
  pointer-events: none;
}

.header-nav {
  display: flex;
  align-items: center;
  gap: 4px;
}
.header-nav a {
  color: #fff;
  padding: 8px 16px;
  border-radius: var(--radius-sm);
  font-size: 0.9rem;
  transition: background 0.2s;
}
.header-nav a:hover { background: var(--primary-lighter); color: var(--accent); }
.header-nav .nav-donate {
  background: var(--accent);
  color: var(--primary);
  font-weight: 600;
  margin-left: 8px;
}
.header-nav .nav-donate:hover { background: var(--accent-hover); color: var(--primary); }

.hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  background: none;
  border: none;
  cursor: pointer;
  padding: 8px;
  z-index: 101;
}
.hamburger span {
  display: block;
  width: 24px;
  height: 2px;
  background: #fff;
  border-radius: 2px;
  transition: all 0.3s;
}
.hamburger.active span:nth-child(1) { transform: rotate(45deg) translate(5px, 5px); }
.hamburger.active span:nth-child(2) { opacity: 0; }
.hamburger.active span:nth-child(3) { transform: rotate(-45deg) translate(5px, -5px); }

/* ── Banner ── */
.banner {
  background: var(--bg-cream);
  border-bottom: 1px solid var(--border);
  padding: 10px 0;
}
.banner-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 0.9rem;
  color: var(--text-secondary);
}
.banner-inner a { font-weight: 600; color: var(--link); }
.banner-inner a:hover { text-decoration: underline; }
.banner-dot {
  width: 6px; height: 6px;
  background: var(--accent);
  border-radius: 50%;
  flex-shrink: 0;
}

/* ── Featured Article ── */
.featured {
  max-width: var(--max-width);
  margin: 40px auto 0;
  padding: 0 24px;
}
.featured-card {
  display: grid;
  grid-template-columns: 1fr 1fr;
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: var(--bg);
  border: 1px solid var(--border);
  transition: box-shadow 0.2s;
}
.featured-card:hover { box-shadow: var(--shadow-lg); }
.featured-thumb {
  background: linear-gradient(135deg, #4c1d95 0%, #7c3aed 50%, #a78bfa 100%);
  min-height: 320px;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}
.featured-thumb .thumb-icon {
  font-size: 5rem;
  opacity: 0.3;
  color: #fff;
}
.featured-body {
  padding: 36px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 16px;
}
.featured-body .tag { align-self: flex-start; }
.featured-body h2 {
  font-size: 1.75rem;
  font-weight: 700;
  line-height: 1.3;
  color: var(--text);
}
.featured-body h2 a { color: inherit; }
.featured-body h2 a:hover { color: var(--link); }
.featured-meta {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 0.875rem;
  color: var(--text-muted);
}
.featured-meta .author { font-weight: 600; color: var(--text); }

/* ── Article Grid ── */
.article-section {
  max-width: var(--max-width);
  margin: 48px auto;
  padding: 0 24px;
}
.section-title {
  font-size: 1.5rem;
  font-weight: 700;
  margin-bottom: 28px;
  color: var(--text);
}
.article-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}
.article-card {
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: box-shadow 0.2s, transform 0.2s;
}
.article-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}
.card-thumb {
  height: 180px;
  position: relative;
  overflow: hidden;
}
.card-thumb-inner {
  width: 100%; height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 3rem;
  opacity: 0.2;
  color: #fff;
}
.card-tag-overlay {
  position: absolute;
  top: 12px;
  left: 12px;
}
.card-body {
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.card-body h3 {
  font-size: 1.1rem;
  font-weight: 600;
  line-height: 1.4;
}
.card-body h3 a { color: var(--text); }
.card-body h3 a:hover { color: var(--link); }
.card-meta {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 0.8rem;
  color: var(--text-muted);
}

/* ── Tags ── */
.tag {
  display: inline-block;
  padding: 3px 10px;
  border-radius: 100px;
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  white-space: nowrap;
}
.tag-ai { background: var(--tag-ai-bg); color: var(--tag-ai); }
.tag-scraping { background: var(--tag-scraping-bg); color: var(--tag-scraping); }
.tag-databases { background: var(--tag-databases-bg); color: var(--tag-databases); }
.tag-elasticsearch { background: var(--tag-elasticsearch-bg); color: var(--tag-elasticsearch); }
.tag-data-eng { background: var(--tag-data-eng-bg); color: var(--tag-data-eng); }
.tag-js { background: #fef3c7; color: #92400e; }
.tag-python { background: #dbeafe; color: #1e40af; }
.tag-general { background: #eef2ff; color: #3730a3; }
.tag-react { background: #ecfeff; color: #155e75; }
.tag-tech { background: #f0fdf4; color: #166534; }
.tag-youtube { background: #fef2f2; color: #991b1b; }
.tag-startup { background: #fdf4ff; color: #86198f; }
.tag-design { background: #fff7ed; color: #9a3412; }
.tag-productivity { background: #f0fdfa; color: #115e59; }
.tag-life { background: #fefce8; color: #854d0e; }
.tag-css { background: #eff6ff; color: #1e40af; }
.tag-self { background: #f5f3ff; color: #5b21b6; }
.tag-node { background: #ecfdf5; color: #065f46; }
.tag-sheets { background: #f0fdf4; color: #166534; }

/* ── Avatar ── */
.avatar {
  width: 28px; height: 28px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.7rem;
  font-weight: 700;
  color: #fff;
  flex-shrink: 0;
}
.avatar-sm { width: 24px; height: 24px; font-size: 0.6rem; }

/* ── Load More ── */
.load-more-wrap {
  text-align: center;
  margin-top: 36px;
}
.load-more-btn {
  padding: 14px 40px;
  border: 2px solid var(--border);
  border-radius: 100px;
  background: var(--bg);
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--text);
  cursor: pointer;
  font-family: var(--font);
  transition: all 0.2s;
}
.load-more-btn:hover {
  border-color: var(--primary);
  background: var(--primary);
  color: #fff;
}
.load-more-btn:active { transform: scale(0.98); }

/* ── Footer ── */
.site-footer {
  background: var(--primary);
  color: #ccc;
  padding: 48px 24px 32px;
  margin-top: 64px;
}
.footer-inner {
  max-width: var(--max-width);
  margin: 0 auto;
}
.footer-mission {
  max-width: 680px;
  margin-bottom: 32px;
  font-size: 0.9rem;
  line-height: 1.7;
  color: var(--text-light);
}
.footer-guides h4 {
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--accent);
  margin-bottom: 12px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}
.footer-guides .guide-links {
  display: flex;
  flex-wrap: wrap;
  gap: 6px 16px;
  margin-bottom: 32px;
  font-size: 0.875rem;
}
.footer-guides .guide-links a { color: var(--text-light); }
.footer-guides .guide-links a:hover { color: #fff; }
.footer-guides .guide-links span { color: var(--text-muted); }
.footer-links {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 20px;
  font-size: 0.8rem;
  border-top: 1px solid var(--primary-lighter);
  padding-top: 24px;
}
.footer-links a { color: var(--text-muted); }
.footer-links a:hover { color: #fff; }

/* ── Learn Page ── */
.learn-welcome {
  max-width: var(--max-width);
  margin: 40px auto 0;
  padding: 0 24px;
  text-align: center;
}
.learn-welcome h1 {
  font-size: 2rem;
  font-weight: 700;
  margin-bottom: 8px;
}
.learn-welcome p { color: var(--text-muted); font-size: 1.05rem; }
.learn-welcome .signin-link {
  display: inline-block;
  margin-top: 12px;
  padding: 8px 24px;
  background: var(--accent);
  color: var(--primary);
  font-weight: 600;
  border-radius: 100px;
  font-size: 0.9rem;
}
.learn-welcome .signin-link:hover { background: var(--accent-hover); color: var(--primary); }

.curriculum-section {
  max-width: var(--max-width);
  margin: 48px auto;
  padding: 0 24px;
}
.curriculum-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}
.curriculum-card {
  display: flex;
  align-items: flex-start;
  gap: 16px;
  padding: 24px;
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  transition: box-shadow 0.2s;
}
.curriculum-card:hover { box-shadow: var(--shadow); }
.curriculum-icon {
  width: 48px; height: 48px;
  border-radius: var(--radius);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
  flex-shrink: 0;
}
.curriculum-card h3 { font-size: 0.95rem; font-weight: 600; line-height: 1.4; }
.curriculum-meta { font-size: 0.8rem; color: var(--text-muted); margin-top: 4px; }

.daily-challenge {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 32px 24px;
  background: var(--bg-cream);
  border-radius: var(--radius-lg);
}
.daily-challenge-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 16px;
}
.daily-challenge h3 { font-size: 1.1rem; font-weight: 600; }
.daily-challenge .challenge-links { display: flex; gap: 16px; }
.daily-challenge .challenge-links a {
  padding: 10px 24px;
  border-radius: 100px;
  font-weight: 600;
  font-size: 0.9rem;
}
.btn-primary {
  background: var(--accent);
  color: var(--primary);
}
.btn-primary:hover { background: var(--accent-hover); color: var(--primary); }
.btn-secondary {
  border: 2px solid var(--border);
  color: var(--text);
}
.btn-secondary:hover { border-color: var(--text); color: var(--text); }

.course-section {
  max-width: var(--max-width);
  margin: 48px auto;
  padding: 0 24px;
}
.course-section h2 { font-size: 1.35rem; font-weight: 700; margin-bottom: 20px; }
.course-list {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 12px;
}
.course-item {
  padding: 16px 20px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  display: flex;
  align-items: center;
  gap: 12px;
  transition: background 0.2s;
}
.course-item:hover { background: var(--bg-light); }
.course-item .course-dot {
  width: 8px; height: 8px;
  border-radius: 50%;
  background: var(--accent);
  flex-shrink: 0;
}
.course-item .course-badge {
  font-size: 0.7rem;
  font-weight: 600;
  padding: 2px 8px;
  border-radius: 100px;
  background: var(--accent-light);
  color: var(--primary);
  white-space: nowrap;
}

/* ── Donate Page ── */
.donate-hero {
  max-width: var(--max-width);
  margin: 48px auto;
  padding: 0 24px;
  text-align: center;
}
.donate-hero h1 {
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--text);
  margin-bottom: 16px;
}
.donate-hero p {
  max-width: 640px;
  margin: 0 auto;
  color: var(--text-secondary);
  font-size: 1.1rem;
  line-height: 1.7;
}
.donate-form-wrap {
  max-width: 520px;
  margin: 40px auto;
  padding: 36px;
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow);
}
.amount-tabs {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
  margin-bottom: 20px;
}
.amount-tab {
  padding: 14px 8px;
  border: 2px solid var(--border);
  border-radius: var(--radius);
  background: var(--bg);
  font-size: 1.15rem;
  font-weight: 700;
  cursor: pointer;
  font-family: var(--font);
  color: var(--text);
  transition: all 0.2s;
  text-align: center;
}
.amount-tab:hover { border-color: var(--accent); }
.amount-tab.active {
  border-color: var(--accent);
  background: var(--accent);
  color: var(--primary);
}
.donation-description {
  text-align: center;
  font-size: 0.9rem;
  color: var(--text-secondary);
  margin-bottom: 24px;
  padding: 16px;
  background: var(--bg-light);
  border-radius: var(--radius);
  min-height: 72px;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.3s;
}
.donate-btn {
  display: block;
  width: 100%;
  padding: 16px;
  background: var(--accent);
  color: var(--primary);
  border: none;
  border-radius: var(--radius);
  font-size: 1.1rem;
  font-weight: 700;
  cursor: pointer;
  font-family: var(--font);
  transition: background 0.2s;
}
.donate-btn:hover { background: var(--accent-hover); }
.donate-sub {
  text-align: center;
  font-size: 0.8rem;
  color: var(--text-muted);
  margin-top: 12px;
}
.donate-sub a { color: var(--link); }

.benefits-section {
  max-width: var(--max-width);
  margin: 48px auto;
  padding: 0 24px;
}
.benefits-section h2 { font-size: 1.5rem; font-weight: 700; margin-bottom: 20px; }
.benefits-list {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 12px;
}
.benefit-item {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 16px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
}
.benefit-icon {
  width: 24px; height: 24px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--accent);
  flex-shrink: 0;
  font-size: 1.1rem;
}

.initiatives-section {
  max-width: var(--max-width);
  margin: 48px auto;
  padding: 0 24px;
}
.initiatives-section h2 { font-size: 1.5rem; font-weight: 700; margin-bottom: 20px; }
.initiative-list { display: flex; flex-direction: column; gap: 12px; }
.initiative-item {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 16px 20px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  font-size: 0.95rem;
}
.initiative-dot {
  width: 10px; height: 10px;
  border-radius: 50%;
  background: var(--accent);
  flex-shrink: 0;
}

.achievements-section {
  max-width: var(--max-width);
  margin: 48px auto;
  padding: 0 24px;
}
.achievements-section h2 { font-size: 1.5rem; font-weight: 700; margin-bottom: 20px; }
.achievements-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.achievements-list li {
  padding: 18px 20px;
  border-left: 3px solid var(--accent);
  background: var(--bg-light);
  border-radius: 0 var(--radius-sm) var(--radius-sm) 0;
  font-size: 0.95rem;
  color: var(--text-secondary);
}
.achievements-list li strong {
  color: var(--text);
  display: block;
  font-size: 1.3rem;
  margin-bottom: 2px;
}

/* ── FAQ Accordion ── */
.faq-section {
  max-width: var(--max-width);
  margin: 48px auto;
  padding: 0 24px;
}
.faq-section h2 { font-size: 1.5rem; font-weight: 700; margin-bottom: 24px; }
.faq-list { display: flex; flex-direction: column; gap: 8px; }
.faq-item { border: 1px solid var(--border); border-radius: var(--radius); overflow: hidden; }
.faq-question {
  width: 100%;
  padding: 18px 20px;
  background: var(--bg);
  border: none;
  text-align: left;
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--text);
  cursor: pointer;
  font-family: var(--font);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  transition: background 0.2s;
}
.faq-question:hover { background: var(--bg-light); }
.faq-question .faq-arrow {
  width: 20px; height: 20px;
  flex-shrink: 0;
  transition: transform 0.3s;
  color: var(--text-muted);
}
.faq-item.open .faq-arrow { transform: rotate(180deg); color: var(--accent); }
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.35s ease, padding 0.35s ease;
}
.faq-item.open .faq-answer {
  max-height: 300px;
  padding: 0 20px 18px;
}
.faq-answer p {
  font-size: 0.9rem;
  color: var(--text-secondary);
  line-height: 1.7;
  padding-top: 4px;
  border-top: 1px solid var(--border-light);
}

/* ── Tag Pages ── */
.tag-header-section {
  max-width: var(--max-width);
  margin: 40px auto 0;
  padding: 0 24px;
}
.tag-header-section h1 {
  font-size: 2rem;
  font-weight: 700;
  margin-bottom: 6px;
}
.tag-header-section h1 .tag-label {
  font-size: 1.5rem;
  vertical-align: middle;
}
.tag-post-count {
  font-size: 1rem;
  color: var(--text-muted);
}
.popular-tags-section {
  max-width: var(--max-width);
  margin: 28px auto;
  padding: 0 24px;
}
.popular-tags-section h3 {
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 12px;
}
.popular-tags-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
.popular-tag-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 14px;
  border: 1px solid var(--border);
  border-radius: 100px;
  font-size: 0.8rem;
  font-weight: 500;
  color: var(--text-secondary);
  background: var(--bg);
  transition: all 0.2s;
  white-space: nowrap;
}
.popular-tag-chip:hover {
  border-color: var(--text-muted);
  background: var(--bg-light);
}
.popular-tag-chip .chip-count {
  color: var(--text-muted);
  font-size: 0.75rem;
}

/* ── Section Wrapper ── */
.section-wrap {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

/* ── Responsive ── */
@media (max-width: 1024px) {
  .article-grid { grid-template-columns: repeat(2, 1fr); }
  .curriculum-grid { grid-template-columns: repeat(2, 1fr); }
  .featured-card { grid-template-columns: 1fr; }
  .featured-thumb { min-height: 220px; }
}

@media (max-width: 768px) {
  .header-search { display: none; }
  .header-nav { display: none; }
  .header-nav.open {
    display: flex;
    flex-direction: column;
    position: absolute;
    top: var(--header-height);
    left: 0;
    right: 0;
    background: var(--primary);
    padding: 16px 24px;
    gap: 4px;
    border-top: 1px solid var(--primary-lighter);
  }
  .header-nav.open a {
    padding: 12px 16px;
    width: 100%;
    border-radius: var(--radius-sm);
  }
  .header-nav .nav-donate { margin-left: 0; }
  .hamburger { display: flex; }
  .article-grid { grid-template-columns: 1fr; }
  .curriculum-grid { grid-template-columns: 1fr; }
  .course-list { grid-template-columns: 1fr; }
  .benefits-list { grid-template-columns: 1fr; }
  .featured-card { grid-template-columns: 1fr; }
  .featured-thumb { min-height: 200px; }
  .featured-body { padding: 24px; }
  .featured-body h2 { font-size: 1.35rem; }
  .amount-tabs { grid-template-columns: repeat(4, 1fr); }
  .amount-tab { font-size: 1rem; padding: 12px 4px; }
  .donate-hero h1 { font-size: 1.75rem; }
  .daily-challenge-inner { flex-direction: column; text-align: center; }
  .banner-inner { font-size: 0.8rem; }
}

@media (max-width: 480px) {
  .amount-tabs { grid-template-columns: repeat(2, 1fr); }
  .header-logo { font-size: 1rem; }
  .section-title { font-size: 1.25rem; }
}

raw_arguments.content:
/* OpenLearnHub — Design System */
:root {
  --primary: #0a0a23;
  --primary-light: #1a1a3e;
  --primary-lighter: #2a2a4e;
  --accent: #FEAC32;
  --accent-hover: #e5991f;
  --accent-light: #fff3d6;
  --link: #002EAD;
  --link-hover: #001f7a;
  --bg: #ffffff;
  --bg-light: #f8f9fa;
  --bg-cream: #fef9ef;
  --bg-warm: #fffbf5;
  --text: #1a1a2e;
  --text-secondary: #4b5563;
  --text-muted: #6b7280;
  --text-light: #9ca3af;
  --border: #e5e7eb;
  --border-light: #f0f0f5;
  --radius: 8px;
  --radius-lg: 12px;
  --radius-sm: 6px;
  --shadow-sm: 0 1px 3px rgba(0,0,0,0.06);
  --shadow: 0 2px 8px rgba(0,0,0,0.08);
  --shadow-lg: 0 4px 20px rgba(0,0,0,0.1);
  --max-width: 1200px;
  --header-height: 64px;
  --font: 'Inter', system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  --tag-ai: #7c3aed;
  --tag-scraping: #059669;
  --tag-databases: #ea580c;
  --tag-elasticsearch: #0d9488;
  --tag-data-eng: #dc2626;
  --tag-js: #d97706;
  --tag-python: #2563eb;
  --tag-general: #4f46e5;
  --tag-react: #0891b2;
  --tag-ai-bg: #f5f3ff;
  --tag-scraping-bg: #ecfdf5;
  --tag-databases-bg: #fff7ed;
  --tag-elasticsearch-bg: #f0fdfa;
  --tag-data-eng-bg: #fef2f2;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

body {
  font-family: var(--font);
  color: var(--text);
  background: var(--bg);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

img { max-width: 100%; display: block; }
a { color: var(--link); text-decoration: none; }
a:hover { color: var(--link-hover); }
ul { list-style: none; }

/* ── Header ── */
.site-header {
  background: var(--primary);
  color: #fff;
  position: sticky;
  top: 0;
  z-index: 100;
  height: var(--header-height);
}
.header-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
  height: 100%;
  display: flex;
  align-items: center;
  gap: 24px;
}
.header-logo {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 1.25rem;
  font-weight: 700;
  color: #fff;
  white-space: nowrap;
}
.header-logo:hover { color: var(--accent); }
.header-logo-icon {
  width: 32px; height: 32px;
  background: var(--accent);
  color: var(--primary);
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
  font-size: 1rem;
  flex-shrink: 0;
}

.header-search {
  flex: 1;
  max-width: 420px;
  position: relative;
}
.header-search input {
  width: 100%;
  padding: 8px 12px 8px 36px;
  border-radius: 20px;
  border: none;
  background: var(--primary-lighter);
  color: #fff;
  font-size: 0.875rem;
  font-family: var(--font);
  outline: none;
  transition: background 0.2s;
}
.header-search input::placeholder { color: var(--text-light); }
.header-search input:focus { background: #3a3a5e; }
.header-search .search-icon {
  position: absolute;
  left: 12px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--text-light);
  pointer-events: none;
}

.header-nav {
  display: flex;
  align-items: center;
  gap: 4px;
}
.header-nav a {
  color: #fff;
  padding: 8px 16px;
  border-radius: var(--radius-sm);
  font-size: 0.9rem;
  transition: background 0.2s;
}
.header-nav a:hover { background: var(--primary-lighter); color: var(--accent); }
.header-nav .nav-donate {
  background: var(--accent);
  color: var(--primary);
  font-weight: 600;
  margin-left: 8px;
}
.header-nav .nav-donate:hover { background: var(--accent-hover); color: var(--primary); }

.hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  background: none;
  border: none;
  cursor: pointer;
  padding: 8px;
  z-index: 101;
}
.hamburger span {
  display: block;
  width: 24px;
  height: 2px;
  background: #fff;
  border-radius: 2px;
  transition: all 0.3s;
}
.hamburger.active span:nth-child(1) { transform: rotate(45deg) translate(5px, 5px); }
.hamburger.active span:nth-child(2) { opacity: 0; }
.hamburger.active span:nth-child(3) { transform: rotate(-45deg) translate(5px, -5px); }

/* ── Banner ── */
.banner {
  background: var(--bg-cream);
  border-bottom: 1px solid var(--border);
  padding: 10px 0;
}
.banner-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 0.9rem;
  color: var(--text-secondary);
}
.banner-inner a { font-weight: 600; color: var(--link); }
.banner-inner a:hover { text-decoration: underline; }
.banner-dot {
  width: 6px; height: 6px;
  background: var(--accent);
  border-radius: 50%;
  flex-shrink: 0;
}

/* ── Featured Article ── */
.featured {
  max-width: var(--max-width);
  margin: 40px auto 0;
  padding: 0 24px;
}
.featured-card {
  display: grid;
  grid-template-columns: 1fr 1fr;
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: var(--bg);
  border: 1px solid var(--border);
  transition: box-shadow 0.2s;
}
.featured-card:hover { box-shadow: var(--shadow-lg); }
.featured-thumb {
  background: linear-gradient(135deg, #4c1d95 0%, #7c3aed 50%, #a78bfa 100%);
  min-height: 320px;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}
.featured-thumb .thumb-icon {
  font-size: 5rem;
  opacity: 0.3;
  color: #fff;
}
.featured-body {
  padding: 36px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 16px;
}
.featured-body .tag { align-self: flex-start; }
.featured-body h2 {
  font-size: 1.75rem;
  font-weight: 700;
  line-height: 1.3;
  color: var(--text);
}
.featured-body h2 a { color: inherit; }
.featured-body h2 a:hover { color: var(--link); }
.featured-meta {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 0.875rem;
  color: var(--text-muted);
}
.featured-meta .author { font-weight: 600; color: var(--text); }

/* ── Article Grid ── */
.article-section {
  max-width: var(--max-width);
  margin: 48px auto;
  padding: 0 24px;
}
.section-title {
  font-size: 1.5rem;
  font-weight: 700;
  margin-bottom: 28px;
  color: var(--text);
}
.article-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}
.article-card {
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: box-shadow 0.2s, transform 0.2s;
}
.article-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}
.card-thumb {
  height: 180px;
  position: relative;
  overflow: hidden;
}
.card-thumb-inner {
  width: 100%; height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 3rem;
  opacity: 0.2;
  color: #fff;
}
.card-tag-overlay {
  position: absolute;
  top: 12px;
  left: 12px;
}
.card-body {
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.card-body h3 {
  font-size: 1.1rem;
  font-weight: 600;
  line-height: 1.4;
}
.card-body h3 a { color: var(--text); }
.card-body h3 a:hover { color: var(--link); }
.card-meta {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 0.8rem;
  color: var(--text-muted);
}

/* ── Tags ── */
.tag {
  display: inline-block;
  padding: 3px 10px;
  border-radius: 100px;
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  white-space: nowrap;
}
.tag-ai { background: var(--tag-ai-bg); color: var(--tag-ai); }
.tag-scraping { background: var(--tag-scraping-bg); color: var(--tag-scraping); }
.tag-databases { background: var(--tag-databases-bg); color: var(--tag-databases); }
.tag-elasticsearch { background: var(--tag-elasticsearch-bg); color: var(--tag-elasticsearch); }
.tag-data-eng { background: var(--tag-data-eng-bg); color: var(--tag-data-eng); }
.tag-js { background: #fef3c7; color: #92400e; }
.tag-python { background: #dbeafe; color: #1e40af; }
.tag-general { background: #eef2ff; color: #3730a3; }
.tag-react { background: #ecfeff; color: #155e75; }
.tag-tech { background: #f0fdf4; color: #166534; }
.tag-youtube { background: #fef2f2; color: #991b1b; }
.tag-startup { background: #fdf4ff; color: #86198f; }
.tag-design { background: #fff7ed; color: #9a3412; }
.tag-productivity { background: #f0fdfa; color: #115e59; }
.tag-life { background: #fefce8; color: #854d0e; }
.tag-css { background: #eff6ff; color: #1e40af; }
.tag-self { background: #f5f3ff; color: #5b21b6; }
.tag-node { background: #ecfdf5; color: #065f46; }
.tag-sheets { background: #f0fdf4; color: #166534; }

/* ── Avatar ── */
.avatar {
  width: 28px; height: 28px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.7rem;
  font-weight: 700;
  color: #fff;
  flex-shrink: 0;
}
.avatar-sm { width: 24px; height: 24px; font-size: 0.6rem; }

/* ── Load More ── */
.load-more-wrap {
  text-align: center;
  margin-top: 36px;
}
.load-more-btn {
  padding: 14px 40px;
  border: 2px solid var(--border);
  border-radius: 100px;
  background: var(--bg);
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--text);
  cursor: pointer;
  font-family: var(--font);
  transition: all 0.2s;
}
.load-more-btn:hover {
  border-color: var(--primary);
  background: var(--primary);
  color: #fff;
}
.load-more-btn:active { transform: scale(0.98); }

/* ── Footer ── */
.site-footer {
  background: var(--primary);
  color: #ccc;
  padding: 48px 24px 32px;
  margin-top: 64px;
}
.footer-inner {
  max-width: var(--max-width);
  margin: 0 auto;
}
.footer-mission {
  max-width: 680px;
  margin-bottom: 32px;
  font-size: 0.9rem;
  line-height: 1.7;
  color: var(--text-light);
}
.footer-guides h4 {
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--accent);
  margin-bottom: 12px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}
.footer-guides .guide-links {
  display: flex;
  flex-wrap: wrap;
  gap: 6px 16px;
  margin-bottom: 32px;
  font-size: 0.875rem;
}
.footer-guides .guide-links a { color: var(--text-light); }
.footer-guides .guide-links a:hover { color: #fff; }
.footer-guides .guide-links span { color: var(--text-muted); }
.footer-links {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 20px;
  font-size: 0.8rem;
  border-top: 1px solid var(--primary-lighter);
  padding-top: 24px;
}
.footer-links a { color: var(--text-muted); }
.footer-links a:hover { color: #fff; }

/* ── Learn Page ── */
.learn-welcome {
  max-width: var(--max-width);
  margin: 40px auto 0;
  padding: 0 24px;
  text-align: center;
}
.learn-welcome h1 {
  font-size: 2rem;
  font-weight: 700;
  margin-bottom: 8px;
}
.learn-welcome p { color: var(--text-muted); font-size: 1.05rem; }
.learn-welcome .signin-link {
  display: inline-block;
  margin-top: 12px;
  padding: 8px 24px;
  background: var(--accent);
  color: var(--primary);
  font-weight: 600;
  border-radius: 100px;
  font-size: 0.9rem;
}
.learn-welcome .signin-link:hover { background: var(--accent-hover); color: var(--primary); }

.curriculum-section {
  max-width: var(--max-width);
  margin: 48px auto;
  padding: 0 24px;
}
.curriculum-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}
.curriculum-card {
  display: flex;
  align-items: flex-start;
  gap: 16px;
  padding: 24px;
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  transition: box-shadow 0.2s;
}
.curriculum-card:hover { box-shadow: var(--shadow); }
.curriculum-icon {
  width: 48px; height: 48px;
  border-radius: var(--radius);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
  flex-shrink: 0;
}
.curriculum-card h3 { font-size: 0.95rem; font-weight: 600; line-height: 1.4; }
.curriculum-meta { font-size: 0.8rem; color: var(--text-muted); margin-top: 4px; }

.daily-challenge {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 32px 24px;
  background: var(--bg-cream);
  border-radius: var(--radius-lg);
}
.daily-challenge-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 16px;
}
.daily-challenge h3 { font-size: 1.1rem; font-weight: 600; }
.daily-challenge .challenge-links { display: flex; gap: 16px; }
.daily-challenge .challenge-links a {
  padding: 10px 24px;
  border-radius: 100px;
  font-weight: 600;
  font-size: 0.9rem;
}
.btn-primary {
  background: var(--accent);
  color: var(--primary);
}
.btn-primary:hover { background: var(--accent-hover); color: var(--primary); }
.btn-secondary {
  border: 2px solid var(--border);
  color: var(--text);
}
.btn-secondary:hover { border-color: var(--text); color: var(--text); }

.course-section {
  max-width: var(--max-width);
  margin: 48px auto;
  padding: 0 24px;
}
.course-section h2 { font-size: 1.35rem; font-weight: 700; margin-bottom: 20px; }
.course-list {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 12px;
}
.course-item {
  padding: 16px 20px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  display: flex;
  align-items: center;
  gap: 12px;
  transition: background 0.2s;
}
.course-item:hover { background: var(--bg-light); }
.course-item .course-dot {
  width: 8px; height: 8px;
  border-radius: 50%;
  background: var(--accent);
  flex-shrink: 0;
}
.course-item .course-badge {
  font-size: 0.7rem;
  font-weight: 600;
  padding: 2px 8px;
  border-radius: 100px;
  background: var(--accent-light);
  color: var(--primary);
  white-space: nowrap;
}

/* ── Donate Page ── */
.donate-hero {
  max-width: var(--max-width);
  margin: 48px auto;
  padding: 0 24px;
  text-align: center;
}
.donate-hero h1 {
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--text);
  margin-bottom: 16px;
}
.donate-hero p {
  max-width: 640px;
  margin: 0 auto;
  color: var(--text-secondary);
  font-size: 1.1rem;
  line-height: 1.7;
}
.donate-form-wrap {
  max-width: 520px;
  margin: 40px auto;
  padding: 36px;
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow);
}
.amount-tabs {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
  margin-bottom: 20px;
}
.amount-tab {
  padding: 14px 8px;
  border: 2px solid var(--border);
  border-radius: var(--radius);
  background: var(--bg);
  font-size: 1.15rem;
  font-weight: 700;
  cursor: pointer;
  font-family: var(--font);
  color: var(--text);
  transition: all 0.2s;
  text-align: center;
}
.amount-tab:hover { border-color: var(--accent); }
.amount-tab.active {
  border-color: var(--accent);
  background: var(--accent);
  color: var(--primary);
}
.donation-description {
  text-align: center;
  font-size: 0.9rem;
  color: var(--text-secondary);
  margin-bottom: 24px;
  padding: 16px;
  background: var(--bg-light);
  border-radius: var(--radius);
  min-height: 72px;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.3s;
}
.donate-btn {
  display: block;
  width: 100%;
  padding: 16px;
  background: var(--accent);
  color: var(--primary);
  border: none;
  border-radius: var(--radius);
  font-size: 1.1rem;
  font-weight: 700;
  cursor: pointer;
  font-family: var(--font);
  transition: background 0.2s;
}
.donate-btn:hover { background: var(--accent-hover); }
.donate-sub {
  text-align: center;
  font-size: 0.8rem;
  color: var(--text-muted);
  margin-top: 12px;
}
.donate-sub a { color: var(--link); }

.benefits-section {
  max-width: var(--max-width);
  margin: 48px auto;
  padding: 0 24px;
}
.benefits-section h2 { font-size: 1.5rem; font-weight: 700; margin-bottom: 20px; }
.benefits-list {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 12px;
}
.benefit-item {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 16px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
}
.benefit-icon {
  width: 24px; height: 24px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--accent);
  flex-shrink: 0;
  font-size: 1.1rem;
}

.initiatives-section {
  max-width: var(--max-width);
  margin: 48px auto;
  padding: 0 24px;
}
.initiatives-section h2 { font-size: 1.5rem; font-weight: 700; margin-bottom: 20px; }
.initiative-list { display: flex; flex-direction: column; gap: 12px; }
.initiative-item {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 16px 20px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  font-size: 0.95rem;
}
.initiative-dot {
  width: 10px; height: 10px;
  border-radius: 50%;
  background: var(--accent);
  flex-shrink: 0;
}

.achievements-section {
  max-width: var(--max-width);
  margin: 48px auto;
  padding: 0 24px;
}
.achievements-section h2 { font-size: 1.5rem; font-weight: 700; margin-bottom: 20px; }
.achievements-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.achievements-list li {
  padding: 18px 20px;
  border-left: 3px solid var(--accent);
  background: var(--bg-light);
  border-radius: 0 var(--radius-sm) var(--radius-sm) 0;
  font-size: 0.95rem;
  color: var(--text-secondary);
}
.achievements-list li strong {
  color: var(--text);
  display: block;
  font-size: 1.3rem;
  margin-bottom: 2px;
}

/* ── FAQ Accordion ── */
.faq-section {
  max-width: var(--max-width);
  margin: 48px auto;
  padding: 0 24px;
}
.faq-section h2 { font-size: 1.5rem; font-weight: 700; margin-bottom: 24px; }
.faq-list { display: flex; flex-direction: column; gap: 8px; }
.faq-item { border: 1px solid var(--border); border-radius: var(--radius); overflow: hidden; }
.faq-question {
  width: 100%;
  padding: 18px 20px;
  background: var(--bg);
  border: none;
  text-align: left;
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--text);
  cursor: pointer;
  font-family: var(--font);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  transition: background 0.2s;
}
.faq-question:hover { background: var(--bg-light); }
.faq-question .faq-arrow {
  width: 20px; height: 20px;
  flex-shrink: 0;
  transition: transform 0.3s;
  color: var(--text-muted);
}
.faq-item.open .faq-arrow { transform: rotate(180deg); color: var(--accent); }
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.35s ease, padding 0.35s ease;
}
.faq-item.open .faq-answer {
  max-height: 300px;
  padding: 0 20px 18px;
}
.faq-answer p {
  font-size: 0.9rem;
  color: var(--text-secondary);
  line-height: 1.7;
  padding-top: 4px;
  border-top: 1px solid var(--border-light);
}

/* ── Tag Pages ── */
.tag-header-section {
  max-width: var(--max-width);
  margin: 40px auto 0;
  padding: 0 24px;
}
.tag-header-section h1 {
  font-size: 2rem;
  font-weight: 700;
  margin-bottom: 6px;
}
.tag-header-section h1 .tag-label {
  font-size: 1.5rem;
  vertical-align: middle;
}
.tag-post-count {
  font-size: 1rem;
  color: var(--text-muted);
}
.popular-tags-section {
  max-width: var(--max-width);
  margin: 28px auto;
  padding: 0 24px;
}
.popular-tags-section h3 {
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 12px;
}
.popular-tags-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
.popular-tag-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 14px;
  border: 1px solid var(--border);
  border-radius: 100px;
  font-size: 0.8rem;
  font-weight: 500;
  color: var(--text-secondary);
  background: var(--bg);
  transition: all 0.2s;
  white-space: nowrap;
}
.popular-tag-chip:hover {
  border-color: var(--text-muted);
  background: var(--bg-light);
}
.popular-tag-chip .chip-count {
  color: var(--text-muted);
  font-size: 0.75rem;
}

/* ── Section Wrapper ── */
.section-wrap {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

/* ── Responsive ── */
@media (max-width: 1024px) {
  .article-grid { grid-template-columns: repeat(2, 1fr); }
  .curriculum-grid { grid-template-columns: repeat(2, 1fr); }
  .featured-card { grid-template-columns: 1fr; }
  .featured-thumb { min-height: 220px; }
}

@media (max-width: 768px) {
  .header-search { display: none; }
  .header-nav { display: none; }
  .header-nav.open {
    display: flex;
    flex-direction: column;
    position: absolute;
    top: var(--header-height);
    left: 0;
    right: 0;
    background: var(--primary);
    padding: 16px 24px;
    gap: 4px;
    border-top: 1px solid var(--primary-lighter);
  }
  .header-nav.open a {
    padding: 12px 16px;
    width: 100%;
    border-radius: var(--radius-sm);
  }
  .header-nav .nav-donate { margin-left: 0; }
  .hamburger { display: flex; }
  .article-grid { grid-template-columns: 1fr; }
  .curriculum-grid { grid-template-columns: 1fr; }
  .course-list { grid-template-columns: 1fr; }
  .benefits-list { grid-template-columns: 1fr; }
  .featured-card { grid-template-columns: 1fr; }
  .featured-thumb { min-height: 200px; }
  .featured-body { padding: 24px; }
  .featured-body h2 { font-size: 1.35rem; }
  .amount-tabs { grid-template-columns: repeat(4, 1fr); }
  .amount-tab { font-size: 1rem; padding: 12px 4px; }
  .donate-hero h1 { font-size: 1.75rem; }
  .daily-challenge-inner { flex-direction: column; text-align: center; }
  .banner-inner { font-size: 0.8rem; }
}

@media (max-width: 480px) {
  .amount-tabs { grid-template-columns: repeat(2, 1fr); }
  .header-logo { font-size: 1rem; }
  .section-title { font-size: 1.25rem; }
}

